<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder\TenantConfigWelcomeEmailAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigWelcomeEmailAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigWelcomeEmailAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getWelcomeEmail returns null on a freshly created holder.
     */
    public function testWelcomeEmailNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWelcomeEmailAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isWelcomeEmailAssigned());
        $this->assertNull($holder->getWelcomeEmail());
    }
}
class ImplWithTenantConfigWelcomeEmailAttributeHolderUnitTest
{
    use TenantConfigWelcomeEmailAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedWelcomeEmailRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultWelcomeEmail();
    }
}
